    cue: 'Bring das Polster auf die Hüftbeuge. Auf dem Bauch zu liegen ist das einzige wirklich unangenehme an dieser Maschine, und man behebt es durch Verschieben des Polsters, nicht durch mehr Polsterung.',
    howTo: ['Belade die Scheibenaufnahmen gleichmäßig und setze dich in die Maschine, mit dem oberen Rücken am Polster und den Füßen flach auf der Plattform.', 'Ziehe das Hüftpolster beziehungsweise den Bügel über deine Hüfte und stelle es so ein, dass es auf der Hüftbeuge liegt und nicht auf dem Bauch.', 'Setze die Füße so, dass die Schienbeine senkrecht stehen, wenn die Hüfte oben ist, und greife die Haltegriffe.', 'Drücke die Hüfte durch Anspannen der Gesäßmuskeln nach oben, bis die Oberschenkel auf Höhe des Oberkörpers sind, und halte oben kurz.', 'Senke kontrolliert ab, bis die Hüfte kurz vor dem Ende des Bewegungsumfangs ist, und wiederhole für die gewünschte Anzahl an Wiederholungen.'],
